import{_ as i,o as a,c as n,ao as s,j as t,a as o}from"./chunks/framework.B7UvRKha.js";const w=JSON.parse('{"title":"The project chat","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat.md","filePath":"guide/chat.md","lastUpdated":null}'),h={name:"guide/chat.md"},d={class:"MathJax",jax:"SVG",overflow:"linebreak"},r={style:{"vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"5.715ex",height:"1.717ex",role:"img",focusable:"false",viewBox:"0 -748 2526 759"};function l(c,e,g,p,m,u){return a(),n("div",null,[e[21]||(e[21]=s('<h1 id="The-project-chat" tabindex="-1">The project chat <a class="header-anchor" href="#The-project-chat" aria-label="Permalink to &quot;The project chat {#The-project-chat}&quot;">​</a></h1><p>The Chat panel, at the bottom of the Ship of Tools window, shows a project&#39;s Slack channel and posts to it. To connect Slack or to give a project its channel, see <a href="./chat-setup">Setting up Slack</a>.</p><p>Keys are written as on Linux and Windows. On a Mac, press Cmd where this page says Ctrl and Option where it says Alt (<code>Ctrl+Shift+k</code> is Cmd+Shift+k); the window&#39;s own key lists show the Mac&#39;s symbols, such as <code>⇧⌘k</code> (⇧ is Shift, ⌘ is Cmd). A letter in a key is always lowercase: <code>Ctrl+k</code> is Ctrl and k, and <code>Ctrl+Shift+k</code> adds Shift. Keys can be changed; see <a href="./../ref/keybindings">Keybindings</a>.</p><h2 id="What-the-panel-shows" tabindex="-1">What the panel shows <a class="header-anchor" href="#What-the-panel-shows" aria-label="Permalink to &quot;What the panel shows {#What-the-panel-shows}&quot;">​</a></h2><ul><li><p><strong>A session&#39;s channel.</strong> A session is one coding agent, such as Claude Code or Codex, running in one project&#39;s folder. The navigation tree, the window&#39;s left column, has modes: <code>s</code> there shows Sessions mode, which lists the sessions, and <code>f</code> Files mode, which lists the project&#39;s files. The panel shows the channel of the selected session&#39;s project, and follows the selection. A message that says <code>row</code>, such as <code>the row is gone or was replaced</code> or <code>&lt;handle&gt; (row via Ship of Tools)</code>, means a session.</p></li><li><p><strong>Where it is.</strong> The bottom of the window shows one thing at a time: the Julia REPL, a terminal, the monitor, Help or the Chat panel. <code>Ctrl+k</code> shows the Chat panel there and gives it the keys; <code>Ctrl+k</code> again hides it. A click in the messages gives it the keys too, and Escape gives them back to the navigation tree, after closing an open thread first.</p></li><li><p><strong>Its top line.</strong> The panel&#39;s first line reads <code>chat ·</code> and the channel (<code>chat · #lab-general</code>); when more than one Slack workspace is connected it names the workspace first (<code>chat · Alpha Lab · #lab-general</code>). After the channel it says what the panel is waiting for or why it shows nothing; <a href="/ship-of-tools/dev/guide/chat#What-the-top-line-says">What the top line says</a> lists every case.</p></li><li><p><strong>The status line.</strong> What a key did is said on the status line, the line starting <code>status:</code> at the top of the navigation tree, for 10 seconds or until a newer message replaces it; <a href="/ship-of-tools/dev/guide/chat#What-the-status-line-says">What the status line says</a> lists the messages.</p></li><li><p><strong>The computer that runs your sessions.</strong> On each computer, Ship of Tools&#39; service (<code>sotd</code>, a background program apart from the window) runs the sessions there. The chat runs on one computer, which this page calls the computer that runs your sessions: with one computer, that one; with several, the one your <code>hosts.toml</code> (the file that lists your computers, in <code>~/.config/sot</code> on Linux and macOS and <code>%LOCALAPPDATA%\\sot\\config</code> on Windows) names on its <code>hub =</code> line, the line naming the computer the others connect through. The panel&#39;s messages name a computer by its name, or <code>this computer</code> for the one the window runs on; a few messages say <code>the computer that runs your agents</code> for the computer that runs your sessions.</p></li><li><p><strong>Your Slack app, your account and the Slack codes.</strong> What you write goes out under your own Slack account. What your sessions&#39; agents write goes out through your Slack app, the app you made in Slack while setting up, which also reads the channel. Three Slack codes (Slack calls them tokens), pasted during setup and kept on the computer that runs your sessions, let Ship of Tools act in Slack: one posts as you, one lets your Slack app read and post, and one lets it receive new messages.</p></li></ul><h2 id="Keys-in-the-Chat-panel" tabindex="-1">Keys in the Chat panel <a class="header-anchor" href="#Keys-in-the-Chat-panel" aria-label="Permalink to &quot;Keys in the Chat panel {#Keys-in-the-Chat-panel}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Ctrl+k</code></td><td style="text-align:right;">Show or hide the Chat panel.</td></tr><tr><td style="text-align:right;">typing, <code>Ctrl+v</code></td><td style="text-align:right;">Write the message at the panel&#39;s foot; a paste is added whole.</td></tr><tr><td style="text-align:right;"><code>Shift+Enter</code></td><td style="text-align:right;">Start a new line in the message.</td></tr><tr><td style="text-align:right;"><code>Enter</code></td><td style="text-align:right;">Post the message. With nothing typed in a project that has no channel, open the channel list.</td></tr><tr><td style="text-align:right;"><code>Ctrl+u</code></td><td style="text-align:right;">Post the file the preview pane shows, with the message as its comment.</td></tr><tr><td style="text-align:right;"><code>ArrowUp</code>, <code>ArrowDown</code></td><td style="text-align:right;">Mark a message (a highlight that the keys below act on): the first <code>ArrowUp</code> marks the newest, then each press marks the next older or newer one.</td></tr><tr><td style="text-align:right;"><code>ArrowRight</code></td><td style="text-align:right;">Open the marked message&#39;s thread.</td></tr><tr><td style="text-align:right;"><code>ArrowLeft</code></td><td style="text-align:right;">Close the open thread, while nothing is typed.</td></tr><tr><td style="text-align:right;"><code>Escape</code></td><td style="text-align:right;">Close the open thread; with none open, give the keys back to the navigation tree.</td></tr><tr><td style="text-align:right;"><code>PageUp</code>, <code>PageDown</code></td><td style="text-align:right;">Scroll a third of the panel.</td></tr><tr><td style="text-align:right;"><code>Alt+ArrowUp</code>, <code>Alt+ArrowDown</code>, mouse wheel</td><td style="text-align:right;">Scroll one line.</td></tr><tr><td style="text-align:right;"><code>End</code></td><td style="text-align:right;">Go back to the newest message and follow new ones.</td></tr><tr><td style="text-align:right;"><code>Ctrl+c</code></td><td style="text-align:right;">Copy the selected text, or the marked message&#39;s text when nothing is selected.</td></tr><tr><td style="text-align:right;"><code>Ctrl+o</code></td><td style="text-align:right;">Open the marked message&#39;s first picture in the preview pane. A click on a picture opens that one.</td></tr><tr><td style="text-align:right;"><code>Ctrl+Shift+k</code></td><td style="text-align:right;">Open the channel list: change this project&#39;s channel, pick one in another workspace, or connect a workspace.</td></tr></tbody></table><p>While the channel list is open, Up and Down choose, Left and Right show another workspace&#39;s channels, typing narrows the list, Enter picks and Escape closes it.</p><h2 id="Reading" tabindex="-1">Reading <a class="header-anchor" href="#Reading" aria-label="Permalink to &quot;Reading {#Reading}&quot;">​</a></h2><p>The newest message is at the bottom, and the panel follows it: a message that arrives takes the bottom line and lifts the rest. Scroll up to read older messages; while you are scrolled up, the view stays where it is when messages arrive, are edited or are deleted. <code>End</code>, or scrolling down to the newest, follows new messages again. Selecting another session shows its channel from the newest message. A scroll glides to its place over <code>smooth_scroll_ms</code>, a setting in the <code>[display]</code> table of the window&#39;s settings file, <code>settings.toml</code> (in <code>~/.config/sot</code> on Linux and macOS and <code>%LOCALAPPDATA%\\sot\\config</code> on Windows): 150 ms unless you change it, and 0 moves at once.</p><p>Scrolling to the oldest message reads older ones from Slack, up to 256 messages in all, a fixed limit of Ship of Tools; the top line says when no more can be read. An empty channel shows <code>no messages</code>.</p><p>The mark is a lighter band across the message with a blue bar at its left edge. The view moves to keep the marked message in view, and a scroll that leaves it out of view moves the mark to the nearest message still shown.</p><p>Edits and deletes made in Slack reach the newest 100 messages, a fixed limit of Ship of Tools; an older message stays as it was read. A message deleted while you watch stays in its place as <code>(message deleted)</code> until the panel reads the channel again, as it does after a lost connection and when you come back to the channel from another session. The panel keeps the messages of the last two channels it showed, so switching back draws them as soon as the computer that runs your sessions answers, with <code>reading…</code> in the top line until the channel is read again.</p><h2 id="Threads" tabindex="-1">Threads <a class="header-anchor" href="#Threads" aria-label="Permalink to &quot;Threads {#Threads}&quot;">​</a></h2><p>Mark a message with <code>ArrowUp</code> and press <code>ArrowRight</code>: the panel shows the message and its replies, oldest first, and the top line adds <code>· thread</code>. Any message opens this way, with replies or without. While a thread is open, what you write is a reply in it. <code>Escape</code> closes the thread, and so does <code>ArrowLeft</code> while nothing is typed; the mark is back on the message. Selecting another session or hiding the panel closes the thread too.</p><p>A thread is read when it is opened, and again after your own reply in it: a reply someone makes elsewhere while it is open shows when you open the thread again. A very long thread shows its oldest messages, and the top line says <code>the rest of this thread is not shown</code>.</p><p>A message that has replies ends with a line in Slack&#39;s style: <code>2 replies</code> (<code>1 reply</code>) and, when Slack gives its time, <code>Last reply today at 2:44 PM</code>.</p><h2 id="Writing-and-posting" tabindex="-1">Writing and posting <a class="header-anchor" href="#Writing-and-posting" aria-label="Permalink to &quot;Writing and posting {#Writing-and-posting}&quot;">​</a></h2><h3 id="The-foot-of-the-panel" tabindex="-1">The foot of the panel <a class="header-anchor" href="#The-foot-of-the-panel" aria-label="Permalink to &quot;The foot of the panel {#The-foot-of-the-panel}&quot;">​</a></h3><p>While the message box is empty, the foot of the panel shows one line:</p><p><code>&gt; type a message and press Enter to post it</code></p><p>Under it, until the first post from the computer the window runs on is made (from any project), a short explanation follows:</p><p><code>What you post appears in the channel as your own message, from your Slack account. Ctrl+Shift+k changes this project&#39;s channel.</code></p><p>After that first post the explanation is gone for good on that computer; the one-line prompt stays whenever the box is empty. If the computer that runs your sessions runs an older Ship of Tools, which posts as your Slack app, a warning saying so stays there instead. While a thread is open, the foot shows <code>&gt;</code> and <code>reply in thread of</code> the message&#39;s time (<code>reply in thread of 2:14 PM</code>) instead of the prompt.</p><p>As you type, the foot shows <code>&gt;</code> and the last three lines of the message, and a line such as <code>2 lines not shown</code> when it is longer. Each project has its own message, which keeps the place it was begun in (the channel, or the thread open then) through closing the thread, selecting another session and a reconnect; the foot names that place when the top line does not. A message holds about 8 KiB, a fixed limit of Ship of Tools; a key or paste past that is refused whole, with <code>draft is full: nothing added</code> (the draft is your message). It is lost when its session ends or the window closes.</p><h3 id="Your-chat-name" tabindex="-1">Your chat name <a class="header-anchor" href="#Your-chat-name" aria-label="Permalink to &quot;Your chat name {#Your-chat-name}&quot;">​</a></h3><p>If no chat name is set and the computer that runs your sessions runs an older Ship of Tools, which posts as your Slack app, the first time you press Enter with a message typed, the foot asks <code>Your name for chat posts (saved in settings.toml):</code>. Type a name and press Enter: it is saved in <code>[chat] name</code> of <code>settings.toml</code> (see <a href="./../ref/config">the settings reference</a>), and your message stays. Press Enter again to post it. Escape cancels and keeps the message. A name with a quote, a backslash or a control character, or longer than 160 bytes, is refused. Otherwise your posts appear in Slack under your own Slack name, Enter posts with no question, and the chat name is not used. To change the name, edit <code>[chat] name</code> and restart the window.</p><h3 id="What-happens-when-you-post" tabindex="-1">What happens when you post <a class="header-anchor" href="#What-happens-when-you-post" aria-label="Permalink to &quot;What happens when you post {#What-happens-when-you-post}&quot;">​</a></h3><p><code>Enter</code> posts the message once, to the channel or thread the foot names, as your own message from your Slack account. You must be a member of the channel in Slack. While the post waits, the message is frozen: a key or Enter is refused with <code>posting…</code> on the status line. Only Slack&#39;s answer that the post was made clears the message; any other outcome keeps it, and the status line says why. If the answer was lost (<code>may have been posted</code>), look at the channel before posting again: a post is never sent twice on its own.</p><p>A post is plain text: what you type, a <code>&lt;</code> included, arrives as typed, and <code>@here</code> and <code>&lt;!channel&gt;</code> arrive as plain text that pings no one.</p><p>If the computer that runs your sessions holds no Slack code that posts as you (it was connected before Ship of Tools posted as you, or Slack stopped accepting the code), nothing is posted, and the panel shows the post-as-you screen, which asks for that workspace&#39;s Slack codes again, in place of the channel, with your message kept: see <a href="/ship-of-tools/dev/guide/chat-setup#Give-a-connected-workspace-new-Slack-codes">Give a connected workspace new Slack codes</a>.</p><h2 id="Posting-a-file" tabindex="-1">Posting a file <a class="header-anchor" href="#Posting-a-file" aria-label="Permalink to &quot;Posting a file {#Posting-a-file}&quot;">​</a></h2><p><code>Ctrl+u</code> posts the file the preview pane shows, once, as your own message, with what you typed as its comment. The preview pane is the window&#39;s middle column, which shows the file selected in the navigation tree&#39;s Files mode (press <code>f</code> there). The file goes to the channel or thread your message was begun in, or, with nothing typed, to the channel and the thread open then. The status line says <code>shared &lt;name&gt; to &lt;channel&gt;</code> when it is posted, and the message is cleared.</p><p>The file must be a file of the selected session&#39;s folder, at most 16 MiB (a fixed limit of Ship of Tools), and not one of the chat&#39;s own settings files. A picture opened from the chat is not a file of the project, so with one in the preview nothing is posted and the status line says so for 10 seconds: <code>not posted: the preview shows a picture opened from the chat, which is not a file of this project; show a file in the preview, then press Ctrl+u</code>. Select the file in Files mode, click in the Chat panel and press <code>Ctrl+u</code> again. Nothing is posted either while the channel list or the name prompt is open.</p><h2 id="Pictures" tabindex="-1">Pictures <a class="header-anchor" href="#Pictures" aria-label="Permalink to &quot;Pictures {#Pictures}&quot;">​</a></h2><p>A message&#39;s pictures (PNG, JPEG, GIF and WebP) show below its text as square tiles, each with Slack&#39;s thumbnail once it arrives; any other file shows as a line with its name. A click on a tile (pressed and released in place) opens that picture in the preview pane, and <code>Ctrl+o</code> opens the marked message&#39;s first picture. The status line says <code>opening the picture…</code>, then <code>picture shown in the preview</code>, or why it was not opened.</p><p>A picture opened from the chat is not a project file: it has no name in Files mode, <code>Ctrl+u</code> does not post it, and the preview&#39;s own tools (drawing over a picture for the agent, cropping it, its scale bar) do not work on it. Moving the cursor in Files mode, or selecting another session, shows a file again. A very large picture is shown at reduced resolution.</p><h2 id="Selecting-and-copying" tabindex="-1">Selecting and copying <a class="header-anchor" href="#Selecting-and-copying" aria-label="Permalink to &quot;Selecting and copying {#Selecting-and-copying}&quot;">​</a></h2><p>Press the left mouse button on a message&#39;s text and drag to select within that message; the name and time line is not selected. <code>Ctrl+c</code> (or <code>Ctrl+Shift+c</code>) copies the selection as shown: a link&#39;s label, a mention&#39;s name, a style&#39;s text without its marks. With nothing selected it copies the marked message&#39;s text. <code>(edited)</code> is never copied. The status line says <code>copied chat text</code>, or <code>nothing to copy: select text or mark a message</code>. The session&#39;s agent never sees what you select in the chat; it sees only text you select in the preview pane and what you draw there.</p><h2 id="How-messages-look" tabindex="-1">How messages look <a class="header-anchor" href="#How-messages-look" aria-label="Permalink to &quot;How messages look {#How-messages-look}&quot;">​</a></h2><p>The panel is dark, like Slack&#39;s desktop app in dark mode. Each message starts with a header: the author&#39;s name in bold, a small gray badge, and the time on a 12-hour clock (<code>2:14 PM</code>). The badge is <code>AGENT</code> for a post from one of your sessions&#39; agents (sent through your Slack app) and <code>APP</code> for any other post from a Slack app; your own posts carry none. Messages from one author less than five minutes apart on the same day share one header, with a small colored square in the margin; mark such a message to see its time in the margin. A divider names each day (<code>Today</code>, <code>Yesterday</code>, <code>Monday, November 9th</code>). A message Slack marks as edited ends with <code>(edited)</code>.</p>',41)),t("p",null,[e[1]||(e[1]=o("Slack's styles show as styles: ",-1)),e[2]||(e[2]=t("code",null,"*bold*",-1)),e[3]||(e[3]=o(", ",-1)),e[4]||(e[4]=t("code",null,"_italic_",-1)),e[5]||(e[5]=o(", ",-1)),e[6]||(e[6]=t("code",null,"~strike~",-1)),e[7]||(e[7]=o(", ",-1)),t("mjx-container",d,[(a(),n("svg",r,[...e[0]||(e[0]=[s('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math" data-latex="`code`"><g data-mml-node="mo" data-latex="`"><path data-c="2035" d="M60 707C60 699 62 692 65 686L219 430L253 430L136 725C129 740 117 748 100 748C77 748 60 729 60 707Z"></path></g><g data-mml-node="mi" data-latex="c" transform="translate(311,0)"><path data-c="1D450" d="M328 325C328 300 341 287 368 287C404 287 427 318 427 354C427 410 368 442 308 442C239 442 176 412 122 353C68 294 41 229 41 159C41 61 106-11 204-11C257-11 304 2 345 27C379 48 404 69 420 90C427 99 430 106 430 109C430 120 425 126 414 126C409 126 404 122 398 114C365 70 324 42 277 30C246 22 223 18 206 18C149 18 121 53 121 122C121 184 150 274 174 317C198 361 249 413 308 413C346 413 372 402 386 381C355 378 328 358 328 325Z"></path></g><g data-mml-node="mi" data-latex="o" transform="translate(744,0)"><path data-c="1D45C" d="M308 442C239 442 176 412 122 353C68 294 41 229 41 159C41 63 106-11 202-11C272-11 334 19 388 78C442 137 469 201 469 272C469 369 405 442 308 442M389 310C389 287 384 255 374 213C353 130 319 73 272 42C248 26 225 18 203 18C149 18 121 65 121 122C121 180 155 288 178 324C216 383 259 413 307 413C361 413 389 367 389 310Z"></path></g><g data-mml-node="mi" data-latex="d" transform="translate(1229,0)"><path data-c="1D451" d="M429 632L370 389C349 426 320 445 281 445C216 445 159 412 109 345C63 283 40 218 40 151C40 63 91-11 175-11C218-11 260 12 300 59C311 21 345-11 392-11C461-11 483 71 498 145C498 154 493 159 483 159C474 159 468 152 465 138C445 59 421 19 394 19C377 19 368 33 368 60C368 75 370 91 374 107L516 679L516 683C513 690 507 694 499 694C476 694 434 690 374 683C363 682 357 674 357 660C357 650 366 645 384 645C403 645 429 646 429 632M341 376C351 355 356 341 356 332C355 328 354 323 353 316L304 122C301 111 294 99 285 87C248 42 212 19 177 19C138 19 118 49 118 108C118 132 124 168 136 216C157 301 187 359 224 390C244 407 263 415 282 415C309 415 329 402 341 376Z"></path></g><g data-mml-node="mi" data-latex="e" transform="translate(1749,0)"><path data-c="1D452" d="M124 129C124 153 129 186 139 227L188 227C253 227 303 235 339 250C372 264 394 284 405 309C412 326 415 342 415 355C415 410 363 442 307 442C268 442 229 432 190 412C113 372 46 281 46 171C46 69 105-11 204-11C257-11 304 2 345 27C379 48 404 69 420 90C427 99 430 106 430 109C430 120 425 126 414 126C409 126 404 122 398 114C365 70 324 42 277 30C246 22 223 18 206 18C149 18 124 72 124 129M375 355C375 289 311 256 182 256L147 256C166 322 194 366 232 387C262 404 287 413 307 413C343 413 375 391 375 355Z"></path></g><g data-mml-node="mo" data-latex="`" transform="translate(2215,0)"><path data-c="2035" d="M60 707C60 699 62 692 65 686L219 430L253 430L136 725C129 740 117 748 100 748C77 748 60 729 60 707Z"></path></g></g></g>',1)])]))]),e[8]||(e[8]=o(", fenced code blocks and ",-1)),e[9]||(e[9]=t("code",null,">",-1)),e[10]||(e[10]=o(" quotes. Links show their label (a link is not clickable), people as ",-1)),e[11]||(e[11]=t("code",null,"@",-1)),e[12]||(e[12]=o(" and their name, channels as ",-1)),e[13]||(e[13]=t("code",null,"#",-1)),e[14]||(e[14]=o(" and their name, and ",-1)),e[15]||(e[15]=t("code",null,"@here",-1)),e[16]||(e[16]=o(", ",-1)),e[17]||(e[17]=t("code",null,"@channel",-1)),e[18]||(e[18]=o(" and ",-1)),e[19]||(e[19]=t("code",null,"@everyone",-1)),e[20]||(e[20]=o(" by name. A name not looked up yet shows as its label or its ID until the channel is read again. Any other markup shows as typed, in blue.",-1))]),e[22]||(e[22]=s('<h2 id="The-agent-in-the-channel" tabindex="-1">The agent in the channel <a class="header-anchor" href="#The-agent-in-the-channel" aria-label="Permalink to &quot;The agent in the channel {#The-agent-in-the-channel}&quot;">​</a></h2><p>A session&#39;s agent can post to its project&#39;s channel with the command <code>sot-fe chat post</code>, which Ship of Tools installs for agents to run. Its posts appear as <code>&lt;handle&gt; (row via Ship of Tools)</code>, where the handle is the session&#39;s name as Sessions mode shows it, the name it also signs its messages to other sessions with (<a href="./messaging">Agents messaging each other</a>). In the commands below, <code>&lt;ts&gt;</code> is a message&#39;s Slack timestamp, which names it.</p><h3 id="A-reply-from-the-agent" tabindex="-1">A reply from the agent <a class="header-anchor" href="#A-reply-from-the-agent" aria-label="Permalink to &quot;A reply from the agent {#A-reply-from-the-agent}&quot;">​</a></h3><p>The agent runs <code>sot-fe chat post [--thread &lt;ts&gt;] (&lt;text&gt; | --stdin)</code> in the session. The post goes into the thread named by <code>--thread</code>, or else is a new message. It is sent once: the command prints <code>posted &lt;ts&gt;</code> and exits 0; exits 2 with <code>refused</code> and a reason, or <code>limited, wait &lt;n&gt; s</code>, when nothing was posted; and exits 3 with <code>unknown</code> or <code>no answer</code> when the post may exist, in which case the agent does not post it again and reads the thread first. A reply is public to every member of the channel.</p><h3 id="A-figure-from-the-agent" tabindex="-1">A figure from the agent <a class="header-anchor" href="#A-figure-from-the-agent" aria-label="Permalink to &quot;A figure from the agent {#A-figure-from-the-agent}&quot;">​</a></h3><p>Ask the session&#39;s agent to post a figure, and it runs <code>sot-fe chat post [--thread &lt;ts&gt;] --file &lt;path&gt; [&lt;comment&gt; | --stdin]</code> in the session. The file must be in the session&#39;s folder: a relative path is taken from the folder the command runs in, and a path outside the folder or with a <code>..</code> in it is refused before anything is sent. A link inside the folder is followed, so a <code>data/results</code> link to another disk can be posted; the chat&#39;s own settings files are refused. Any regular file of at most 16 MiB (a fixed limit of Ship of Tools) can be posted; Slack shows it under <code>&lt;handle&gt; (row via Ship of Tools)</code>, then the comment. With <code>--thread</code> it is posted into that thread; if it shows in the channel instead, Slack did not take the thread. The command prints <code>posted &lt;ts&gt;</code>, or <code>posted file &lt;id&gt;</code> when Slack names no message, with the same exit codes as a reply.</p><h2 id="Mail-to-the-session" tabindex="-1">Mail to the session <a class="header-anchor" href="#Mail-to-the-session" aria-label="Permalink to &quot;Mail to the session {#Mail-to-the-session}&quot;">​</a></h2><p>Posts in a project&#39;s channel can reach the session&#39;s agent as mail (the messages sessions receive from each other), so the agent can answer in the channel with no window open.</p><p><em>The rest of this section is for whoever administers the computer that runs your sessions.</em></p><p>Mail is off until <code>mail_after</code>, the time from which posts count as mail, is set in <code>chat.toml</code>, the chat&#39;s settings file; <a href="/ship-of-tools/dev/ref/config#chat.toml-and-chat-secrets.toml">the chat configuration</a> says how. Then each new post a channel member makes in a mapped channel (one picked for a project), yours from the panel included, reaches that project&#39;s session as one line of mail. An idle Claude Code session starts on it, a busy one reads it when it finishes what it is doing, and a Codex session gets it without being woken. An agent&#39;s own reply is not mail and does not come back to it. A post missed while the computer was down is filed later, once; the configuration page says how.</p><h2 id="What-the-top-line-says" tabindex="-1">What the top line says <a class="header-anchor" href="#What-the-top-line-says" aria-label="Permalink to &quot;What the top line says {#What-the-top-line-says}&quot;">​</a></h2><p>After the channel, the top line says what the panel is waiting for or why it shows nothing. <code>&lt;computer&gt;</code> is a computer&#39;s name, <code>this computer</code>, or <code>the computer that runs your agents</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">The top line says</th><th style="text-align:right;">What it means</th><th style="text-align:right;">What to do</th></tr></thead><tbody><tr><td style="text-align:right;">(nothing after the channel)</td><td style="text-align:right;">The channel was read whole.</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>reading…</code></td><td style="text-align:right;">The channel is being read.</td><td style="text-align:right;">Wait.</td></tr><tr><td style="text-align:right;"><code>no channel</code></td><td style="text-align:right;">The project has no channel.</td><td style="text-align:right;">Press Enter, or <code>Ctrl+Shift+k</code>, to pick one (<a href="./chat-setup">Setting up Slack</a>).</td></tr><tr><td style="text-align:right;"><code>set up Slack</code>, then a step&#39;s name</td><td style="text-align:right;">Slack is not connected, its saved codes are refused, or its chat did not start.</td><td style="text-align:right;">Follow the screens (<a href="./chat-setup">Setting up Slack</a>).</td></tr><tr><td style="text-align:right;"><code>post as you</code></td><td style="text-align:right;">Your post was refused: no Slack code that posts as you is saved.</td><td style="text-align:right;">Give the workspace new codes, keeping its Slack app (<a href="/ship-of-tools/dev/guide/chat-setup#Give-a-connected-workspace-new-Slack-codes">Setting up Slack</a>).</td></tr><tr><td style="text-align:right;"><code>connecting…</code>, <code>connected</code></td><td style="text-align:right;">The setup&#39;s codes are being checked; they were accepted.</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>choose this project&#39;s channel</code></td><td style="text-align:right;">The channel list is open.</td><td style="text-align:right;">Pick a channel, or press Escape.</td></tr><tr><td style="text-align:right;"><code>your Slack app cannot read this channel</code></td><td style="text-align:right;">Slack says your Slack app is not in the channel: a private channel it was never invited to, or a new app.</td><td style="text-align:right;">In that channel in Slack, type <code>/invite @</code> and the app&#39;s name; the panel says which name.</td></tr><tr><td style="text-align:right;"><code>not up to date: &lt;reason&gt;</code></td><td style="text-align:right;">The channel could not be read whole (<code>no messages read yet</code> when nothing came).</td><td style="text-align:right;">Wait: the panel tries again each minute.</td></tr><tr><td style="text-align:right;"><code>no connection to &lt;computer&gt;</code></td><td style="text-align:right;">The window is not connected to that computer. The messages held stay on screen.</td><td style="text-align:right;">Wait: the panel reads the channel again when the link comes back, and a message you typed is kept.</td></tr><tr><td style="text-align:right;"><code>waiting for &lt;computer&gt; to report this project</code></td><td style="text-align:right;">The window has not yet listed the selected session.</td><td style="text-align:right;">Wait.</td></tr><tr><td style="text-align:right;"><code>the chat does not run on &lt;computer&gt;; ...</code></td><td style="text-align:right;">The project&#39;s session runs on another computer than the one the chat runs on, which <code>hosts.toml</code> names on its <code>hub =</code> line.</td><td style="text-align:right;">Run the project&#39;s session on the computer the chat runs on.</td></tr><tr><td style="text-align:right;"><code>the chat on &lt;computer&gt; is not set up correctly: ...</code></td><td style="text-align:right;"><code>chat.toml</code> or a file of Slack codes was refused.</td><td style="text-align:right;">Run <code>sotd log-path</code> in a terminal on that computer: it prints where the log of Ship of Tools&#39; service is, and the log names the file and line.</td></tr><tr><td style="text-align:right;"><code>the chat is not running on &lt;computer&gt;: ...</code></td><td style="text-align:right;">The chat stopped there.</td><td style="text-align:right;">The log on that computer says why.</td></tr><tr><td style="text-align:right;"><code>the chat on &lt;computer&gt; could not answer: &lt;reason&gt;</code></td><td style="text-align:right;">It refused for another reason.</td><td style="text-align:right;">Wait: the panel asks again after a minute.</td></tr><tr><td style="text-align:right;"><code>Ship of Tools on &lt;computer&gt; has no chat: update it</code></td><td style="text-align:right;">That computer runs an older Ship of Tools.</td><td style="text-align:right;">Update it.</td></tr><tr><td style="text-align:right;"><code>the row is gone or was replaced</code></td><td style="text-align:right;">The session ended or was replaced.</td><td style="text-align:right;">Select the project&#39;s session again.</td></tr><tr><td style="text-align:right;"><code>the row now maps to another channel</code>, <code>the row&#39;s folder maps to no channel</code></td><td style="text-align:right;">The project&#39;s channel changed while it was shown.</td><td style="text-align:right;">Select another session, then this one again: the panel asks afresh.</td></tr><tr><td style="text-align:right;"><code>your Slack plan hides older messages</code>, <code>older messages could not be read</code>, <code>older messages are not read: &lt;reason&gt;</code>, <code>older messages beyond the limit are not shown</code></td><td style="text-align:right;">Scrolling to the oldest found no more to read: Slack keeps older history only on some plans, a read was refused, or the panel&#39;s 256 are full.</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>the thread is not read: &lt;reason&gt;</code>, <code>the rest of this thread is not shown</code></td><td style="text-align:right;">In a thread: a read was refused (the panel tries again by itself), or the thread is longer than the panel shows.</td><td style="text-align:right;"></td></tr></tbody></table><p>The channel shows as <code>#</code> and its name, or as its ID while its name is not known yet. The top line does not say whether Slack itself can be reached from the computer that runs your sessions; when that connection is lost long enough for messages to be missed, the top line says <code>not up to date</code>.</p><h2 id="What-the-status-line-says" tabindex="-1">What the status line says <a class="header-anchor" href="#What-the-status-line-says" aria-label="Permalink to &quot;What the status line says {#What-the-status-line-says}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">The status line says</th><th style="text-align:right;">What to do</th></tr></thead><tbody><tr><td style="text-align:right;"><code>posting…</code></td><td style="text-align:right;">Wait for the post&#39;s answer.</td></tr><tr><td style="text-align:right;"><code>nothing to post</code></td><td style="text-align:right;">Type a message first.</td></tr><tr><td style="text-align:right;"><code>not posted: &lt;reason&gt;</code>, such as <code>you are not in that channel in Slack; join it there first</code></td><td style="text-align:right;">Fix the reason; the message is kept.</td></tr><tr><td style="text-align:right;"><code>not posted: Slack asked for a pause; wait &lt;n&gt; s</code></td><td style="text-align:right;">Wait, then press Enter again.</td></tr><tr><td style="text-align:right;"><code>may have been posted: check the channel before sending it again</code></td><td style="text-align:right;">Look at the channel before posting again.</td></tr><tr><td style="text-align:right;"><code>not posted: update Ship of Tools on &lt;computer&gt;, then post again</code></td><td style="text-align:right;">That computer runs an older Ship of Tools.</td></tr><tr><td style="text-align:right;"><code>not posted: close the screen open in the chat first</code></td><td style="text-align:right;">Close the channel list or the screen shown, then post.</td></tr><tr><td style="text-align:right;"><code>not posted: the chat name is not valid; ...</code></td><td style="text-align:right;">Fix the <code>name =</code> line under <code>[chat]</code> in <code>settings.toml</code>.</td></tr><tr><td style="text-align:right;"><code>draft is full: nothing added</code></td><td style="text-align:right;">The message is at its limit.</td></tr><tr><td style="text-align:right;"><code>not posted: the preview shows no file</code></td><td style="text-align:right;">Select a file in Files mode, then press <code>Ctrl+u</code>.</td></tr><tr><td style="text-align:right;"><code>not posted: the preview shows a picture opened from the chat, ...</code></td><td style="text-align:right;">Select a file in Files mode, then press <code>Ctrl+u</code>.</td></tr><tr><td style="text-align:right;"><code>not posted: the file is not a readable file in the row&#39;s folder</code>, <code>not posted: the file is larger than the chat carries</code></td><td style="text-align:right;">Post a file of the project&#39;s folder, at most 16 MiB.</td></tr><tr><td style="text-align:right;"><code>shared &lt;name&gt; to &lt;channel&gt;</code></td><td style="text-align:right;">The file was posted.</td></tr><tr><td style="text-align:right;"><code>chat name saved to &lt;path&gt;</code></td><td style="text-align:right;">Your chat name is saved; press Enter to post.</td></tr><tr><td style="text-align:right;"><code>no message marked: ArrowUp marks one</code>, <code>the marked message has no picture</code></td><td style="text-align:right;">Mark a message with a picture, then press <code>Ctrl+o</code>.</td></tr><tr><td style="text-align:right;"><code>opening the picture…</code>, <code>picture shown in the preview</code>, <code>picture not opened: &lt;reason&gt;</code></td><td style="text-align:right;">The picture is on its way, shown, or refused.</td></tr><tr><td style="text-align:right;"><code>copied chat text</code>, <code>nothing to copy: select text or mark a message</code></td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>not set: &lt;reason&gt;</code></td><td style="text-align:right;">The channel was not picked; the list stays open and the reason says what to do.</td></tr><tr><td style="text-align:right;"><code>that is not a Slack code: ...</code></td><td style="text-align:right;">During setup: copy the code named, by how it starts.</td></tr><tr><td style="text-align:right;"><code>could not open the browser (...): go to api.slack.com/apps</code></td><td style="text-align:right;">Open that address yourself.</td></tr></tbody></table><h2 id="Moving-the-chat-to-another-computer" tabindex="-1">Moving the chat to another computer <a class="header-anchor" href="#Moving-the-chat-to-another-computer" aria-label="Permalink to &quot;Moving the chat to another computer {#Moving-the-chat-to-another-computer}&quot;">​</a></h2><p><em>For whoever administers your computers.</em></p><p>The chat runs on the computer named on the <code>hub =</code> line of <code>hosts.toml</code>. To move it, change that line and start Ship of Tools&#39; service (<code>sotd</code>, the background program that runs the sessions) on the new computer; nothing else. The old computer&#39;s chat stops within a minute, after filing the one post it is filing, and the new one starts within a minute after that. A post made in the minute around the move can reach its session as mail up to 6 hours late: the new computer finds it only at its next check for missed posts, which runs at least every 6 hours.</p>',19))])}const f=i(h,[["render",l]]);export{w as __pageData,f as default};
